      memberConnection,
      {
        body: {
          userAccountId: userAccountId3,
          roleId: typia.random<string & tags.Format<"uuid">>(),
          departmentId: departmentA.id,
          positionTitle: `Support ${RandomGenerator.alphaNumeric(4)}`,
          employmentType: fullTimeType,
          status: inactiveStatus,
