    } satisfies IHrmTimeTrackingMember.IJoin,
  });
  typia.assert(member);
  const projectId = typia.random<string & tags.Format<"uuid">>();
  const rootTask =
    await generate_random_hrm_time_tracking_member_projects_tasks_create(
