          title: RandomGenerator.name(),
          description: RandomGenerator.paragraph({ sentences: 2 }),
          priority: "medium",
          parentTaskId: childTask.id,
        } satisfies IHrmTimeTrackingTask.ICreate,
      },
    );
  });
}

